\frac{\tan x}{\tan y} + 1 + \frac{\tan y}{\tan x} - 1 &= 6 \\
\frac{\tan y}{\tan x} + 1 + \frac{\tan x}{\tan y} - 1 &= 1.
\end{align*}
Let $a = \frac{\tan x}{\tan y}$. The equations simplify to
\begin{align*}
a + 1 + \frac{1}{a} - 1 &= 6 \\
\frac{1}{a} + 1 + a - 1 &= 1.
\end{align*}
Simplifying further, we get
\begin{align*}
a + \frac{1}{a} &= 6 \\
\frac{1}{a} + a &= 1.
\end{align*}
